def request(
    self,
    method: str,
    params: JsonObject | None,
    *,
    response_model: type[ModelT],
) -> ModelT:
    runtime_fields = {
        "turn/start": ("toolOutput", "turnTrigger", "serviceTierForTurn"),
        "thread/resume": ("excludeTurns",),
        "thread/fork": ("excludeTurns",),
    }
    supplied_fields = [
        field
        for field in runtime_fields.get(method, ())
        if (params or {}).get(field) is not None
    ]
    if supplied_fields:
        try:
            if self._runtime_version == "0.0.0":
                if self._checkout_capabilities is None:
                    raise ValueError(
                        "Cannot verify an unversioned CLI with a custom launch command"
                    )
                supported = self._checkout_capabilities.fields[method]
                if missing := set(supplied_fields) - supported:
                    raise ValueError(
                        f"The checkout does not support {', '.join(sorted(missing))}"
                    )
            else:
                require_runtime_version(self._runtime_version)
        except ValueError as exc:
            raise CodexError(
                f"{method} with {', '.join(supplied_fields)}: {exc}. "
                "Configure CodexConfig.codex_bin with a supported CLI."
            ) from exc
    result = self._request_raw(method, params)
    if not isinstance(result, dict):
        raise CodexError(f"{method} response must be a JSON object")
    return response_model.model_validate(result)

def _request_raw(self, method: str, params: JsonObject | None = None) -> JsonValue:
    """Send a JSON-RPC request and wait for the reader thread to route its response."""
    request_id = str(uuid.uuid4())
    waiter = self._router.create_response_waiter(request_id)

    try:
        message: JsonObject = {"id": request_id, "method": method}
        if params is not None:
            message["params"] = params
        self._write_message(message)
    except BaseException:
        self._router.discard_response_waiter(request_id)
        raise

    item = waiter.get()
    if isinstance(item, BaseException):
        raise item
    return item

def _write_message(self, payload: JsonObject) -> None:
    if self._proc is None or self._proc.stdin is None:
        raise TransportClosedError("Codex process is not running")
    with self._lock:
        self._proc.stdin.write(json.dumps(payload) + "\n")
        self._proc.stdin.flush()

def _reader_loop(self) -> None:
    """Continuously classify transport messages into requests, responses, and events."""
    try:
        while True:
            msg = self._read_message()
            if "method" in msg and "id" in msg:
                response = self._handle_server_request(msg)
                self._write_message({"id": msg["id"], "result": response})
                continue
            if "method" in msg and "id" not in msg:
                method = msg["method"]
                if isinstance(method, str):
                    self._router.route_notification(
                        self._coerce_notification(method, msg.get("params"))
                    )
                continue
            self._router.route_response(msg)
    except BaseException as exc:
        self._router.fail_all(exc)

def route_response(self, msg: dict[str, JsonValue]) -> None:
    """Deliver a JSON-RPC response or error to its request waiter."""

    request_id = msg.get("id")
    with self._lock:
        waiter = self._response_waiters.pop(str(request_id), None)
    if waiter is None:
        return

    if "error" in msg:
        err = msg["error"]
        if isinstance(err, dict):
            waiter.put(
                map_jsonrpc_error(
                    int(err.get("code", -32000)),
                    str(err.get("message", "unknown")),
                    err.get("data"),
                )
            )
        else:
            waiter.put(CodexError("Malformed JSON-RPC error response"))
        return

    waiter.put(msg.get("result"))

def map_jsonrpc_error(code: int, message: str, data: Any = None) -> JsonRpcError:
    """Map a raw JSON-RPC error into a richer SDK exception class."""

    if code == -32700:
        return ParseError(code, message, data)
    if code == -32600:
        return InvalidRequestError(code, message, data)
    if code == -32601:
        return MethodNotFoundError(code, message, data)
    if code == -32602:
        return InvalidParamsError(code, message, data)
    if code == -32603:
        return InternalRpcError(code, message, data)

    if -32099 <= code <= -32000:
        if _is_server_overloaded(data):
            if _contains_retry_limit_text(message):
                return RetryLimitExceededError(code, message, data)
            return ServerBusyError(code, message, data)
        if _contains_retry_limit_text(message):
            return RetryLimitExceededError(code, message, data)
        return CodexRpcError(code, message, data)

    return JsonRpcError(code, message, data)

