def stream(self) -> Iterator[Notification]:
    """Yield only notifications routed to this turn handle."""
    try:
        while True:
            event = self._subscription.next()
            yield event
            if (
                event.method == "turn/completed"
                and isinstance(event.payload, TurnCompletedNotification)
                and event.payload.turn.id == self.id
            ):
                break
    finally:
        self._subscription.close()

def _path_env_key(env: dict[str, str]) -> str:
    if os.name != "nt":
        return "PATH"

    matching_keys = [key for key in env if key.upper() == "PATH"]
    if "Path" in matching_keys:
        return "Path"
    return matching_keys[-1] if matching_keys else "PATH"

def resolve_codex_bin(config: "CodexConfig", ops: CodexBinResolverOps) -> Path:
    if config.codex_bin is not None:
        codex_bin = Path(config.codex_bin)
        if not ops.path_exists(codex_bin):
            raise FileNotFoundError(
                f"Codex binary not found at {codex_bin}. Set CodexConfig.codex_bin "
                "to a valid binary path."
            )
        return codex_bin

    return ops.installed_codex_path()

def _default_codex_bin_resolver_ops() -> CodexBinResolverOps:
    return CodexBinResolverOps(
        installed_codex_path=_installed_codex_path,
        path_exists=lambda path: path.exists(),
    )

def _installed_codex_path_dirs() -> tuple[Path, ...]:
    try:
        from codex_cli_bin import bundled_path_dir
    except (ImportError, AttributeError):
        return ()

    path_dir = bundled_path_dir()
    return (path_dir,) if path_dir is not None else ()

def _prepend_path_dirs(env: dict[str, str], path_dirs: tuple[Path, ...]) -> None:
    if not path_dirs:
        return

    path_key = _path_env_key(env)
    if os.name == "nt":
        for key in list(env):
            if key.upper() == "PATH" and key != path_key:
                env.pop(key)

    path_sep = os.pathsep
    existing_path = env.get(path_key, "")
    path_dir_values = [str(path_dir) for path_dir in path_dirs]
    existing_entries = [
        entry for entry in existing_path.split(path_sep) if entry and entry not in path_dir_values
    ]
    env[path_key] = path_sep.join([*path_dir_values, *existing_entries])

def _start_stderr_drain_thread(self) -> None:
    if self._proc is None or self._proc.stderr is None:
        return

    def _drain() -> None:
        stderr = self._proc.stderr
        if stderr is None:
            return
        for line in stderr:
            self._stderr_lines.append(line.rstrip("\n"))

    self._stderr_thread = threading.Thread(target=_drain, daemon=True)
    self._stderr_thread.start()

def _start_reader_thread(self) -> None:
    """Start the sole stdout reader that fans messages into router queues."""
    if self._proc is None or self._proc.stdout is None:
        return

    self._reader_thread = threading.Thread(target=self._reader_loop, daemon=True)
    self._reader_thread.start()

def _split_user_agent(user_agent: str) -> tuple[str | None, str | None]:
    raw = user_agent.strip()
    if not raw:
        return None, None
    if "/" in raw:
        name, version = raw.split("/", 1)
        return (name or None), (version or None)
    parts = raw.split(maxsplit=1)
    if len(parts) == 2:
        return parts[0], parts[1]
    return raw, None

def require_runtime_version(version: str | None) -> None:
    """Reject unknown or unsupported versions, including prereleases at the minimum."""
    # CLI alpha hotfixes use 0.154.0-alpha.1.2; PEP 440 spells that a1.post2.
    normalized = re.sub(r"-alpha\.(\d+)\.(\d+)$", r"a\1.post\2", version or "")
    try:
        if Version(normalized) >= Version(MINIMUM_RUNTIME_VERSION):
            return
    except InvalidVersion:
        pass
    raise ValueError(
        f"Codex CLI {MINIMUM_RUNTIME_VERSION} or newer is required; "
        f"reported version is {version or 'unknown'!r}"
    )

def next_global_notification(self) -> Notification:
    """Block until the next notification that is not scoped to a turn."""

    item = self._global_notifications.get()
    if isinstance(item, BaseException):
        raise item
    return item

def register_login(self, login_id: str) -> None:
    """Register a queue for one interactive login attempt."""

    login_queue: queue.Queue[NotificationQueueItem] = queue.Queue()
    with self._lock:
        if login_id in self._login_notifications:
            return
        pending = self._pending_login_notifications.pop(login_id, deque())
        self._login_notifications[login_id] = login_queue
    for notification in pending:
        login_queue.put(notification)

def next_login_notification(self, login_id: str) -> Notification:
    """Block until the next notification for a registered login attempt."""

    with self._lock:
        login_queue = self._login_notifications.get(login_id)
    if login_queue is None:
        raise RuntimeError(f"login {login_id!r} is not registered for waiting")
    item = login_queue.get()
    if isinstance(item, BaseException):
        raise item
    return item

def subscribe_turn(self, turn_id: str) -> _TurnSubscription:
    """Attach a consumer starting at the next event for this turn."""
    with self._lock:
        state = self._turn_states.setdefault(turn_id, _TurnState(turn_id))
        return _TurnSubscription(self, state, state.next_event)

def register_turn(self, turn_id: str) -> None:
    """Register the default consumer used by the low-level client API."""
    with self._lock:
        if turn_id not in self._turn_notifications:
            self._turn_notifications[turn_id] = self.subscribe_turn(turn_id)

def unregister_turn(self, turn_id: str) -> None:
    """Close only the low-level consumer, leaving other handles subscribed."""
    with self._lock:
        if subscription := self._turn_notifications.get(turn_id):
            subscription.close()

def next_turn_notification(self, turn_id: str) -> Notification:
    """Block until the next event for the default low-level consumer."""
    with self._lock:
        subscription = self._turn_notifications.get(turn_id)
        if subscription is None:
            raise RuntimeError(f"turn {turn_id!r} is not registered for streaming")
    return subscription.next()

def register_goal(self, thread_id: str) -> _GoalOperationState:
    """Register one thread-scoped logical goal operation before it starts."""
    state = _GoalOperationState(thread_id=thread_id)
    state.activate_turn_routing()
    return self._register_goal(state)

def reserve_goal(self, thread_id: str) -> _GoalOperationState:
    """Reserve a thread route without accepting physical turns yet."""
    return self._register_goal(_GoalOperationState(thread_id=thread_id))

def unregister_goal(self, state: _GoalOperationState) -> None:
    """Stop routing notifications to a completed logical goal operation."""
    with self._lock:
        if self._goal_operations.get(state.thread_id) is state:
            self._goal_operations.pop(state.thread_id)

def _params_dict(
    params: (
        V2ThreadStartParams
        | V2ThreadResumeParams
        | V2ThreadListParams
        | V2ThreadForkParams
        | V2TurnStartParams
        | V2GetAccountParams
        | V2LoginAccountParams
        | JsonObject
        | None
    ),
) -> JsonObject:
    if params is None:
        return {}
    if hasattr(params, "model_dump"):
        dumped = params.model_dump(
            by_alias=True,
            exclude_none=True,
            mode="json",
        )
        if not isinstance(dumped, dict):
            raise TypeError("Expected model_dump() to return dict")
        return dumped
    if isinstance(params, dict):
        return params
    raise TypeError(f"Expected generated params model or dict, got {type(params).__name__}")

def register_login_notifications(self, login_id: str) -> None:
    """Start routing notifications for one interactive login attempt."""
    self._router.register_login(login_id)

def thread_goal_set(
    self,
    thread_id: str,
    *,
    objective: str | None = None,
    status: ThreadGoalStatus | None = None,
) -> ThreadGoalSetResponse:
    """Create or update the persisted goal for a thread."""
    payload: JsonObject = {"threadId": thread_id}
    if objective is not None:
        payload["objective"] = objective
    if status is not None:
        payload["status"] = status.value
    return self.request(
        "thread/goal/set",
        payload,
        response_model=ThreadGoalSetResponse,
    )

def pause_goal(self, thread_id: str) -> ThreadGoalSetResponse:
    """Pause the active goal used by a logical goal turn."""
    return self.thread_goal_set(thread_id, status=ThreadGoalStatus.paused)

def _interrupt_goal_operation(self, state: _GoalOperationState) -> None:
    turn_id = state.turn_for_interrupt()
    if turn_id is None:
        return
    try:
        self.turn_interrupt(state.thread_id, turn_id)
    except InvalidRequestError as exc:
        if not exc.message.startswith("expected active turn id"):
            return
        next_turn_id = _active_turn_id_from_error(exc) or state.current_turn()
        if next_turn_id is None or next_turn_id == turn_id:
            return
        try:
            self.turn_interrupt(state.thread_id, next_turn_id)
        except Exception:
            pass
    except Exception:
        pass

def _active_turn_id_from_error(exc: InvalidRequestError) -> str | None:
    match = re.search(r" but found `?([^`]+)`?$", exc.message)
    return match.group(1) if match is not None else None

def _start_goal_operation(
    self,
    thread_id: str,
    objective: str,
) -> tuple[_GoalOperationState, str]:
    thread = self.thread_read(thread_id).thread
    if not isinstance(thread.status.root, IdleThreadStatus):
        raise InvalidRequestError(
            -32600,
            f"thread must be idle before starting a goal: {thread_id}",
        )
    if thread.ephemeral or thread.path is None:
        raise InvalidRequestError(
            -32600,
            f"thread must be persisted before starting a goal: {thread_id}",
        )

    state = self.reserve_goal_operation(thread_id)
    activated = False
    try:
        self.thread_goal_clear(thread_id)
        state.activate_turn_routing()
        self.thread_goal_set(
            thread_id,
            objective=objective,
            status=ThreadGoalStatus.active,
        )
        activated = True
        turn_id = state.wait_for_start(_GOAL_START_TIMEOUT_S)
        if turn_id is None:
            raise CodexError(
                "timed out waiting for goal turn to start after "
                f"{int(_GOAL_START_TIMEOUT_S)} seconds"
            )
        return state, turn_id
    except BaseException as exc:
        if activated or not isinstance(exc, InvalidRequestError):
            self.cancel_goal_operation(state)
        state.finish()
        self.unregister_goal_operation(state)
        raise

def reserve_goal_operation(self, thread_id: str) -> _GoalOperationState:
    """Reserve a private thread route before replacing its stored goal."""
    return self._router.reserve_goal(thread_id)

def thread_goal_clear(self, thread_id: str) -> ThreadGoalClearResponse:
    """Clear the persisted goal for a thread before replacing it."""
    return self.request(
        "thread/goal/clear",
        {"threadId": thread_id},
        response_model=ThreadGoalClearResponse,
    )

def cancel_goal_operation(self, state: _GoalOperationState) -> None:
    """Best-effort cleanup after a logical goal operation is cancelled."""
    try:
        self.pause_goal(state.thread_id)
    except Exception:
        pass
    self._interrupt_goal_operation(state)

def unregister_goal_operation(self, state: _GoalOperationState) -> None:
    """Release routing state for one logical goal turn."""
    self._router.unregister_goal(state)

def _normalize_input_items(
    self,
    input_items: list[JsonObject] | JsonObject | str,
) -> list[JsonObject]:
    if isinstance(input_items, str):
        return [{"type": "text", "text": input_items}]
    if isinstance(input_items, dict):
        return [input_items]
    return input_items

def pending_turn(self, thread_id: str) -> Iterator[dict[str, int]]:
    """Buffer events from the point a turn/start request is sent."""
    with self._lock:
        cursors = {turn_id: state.next_event for turn_id, state in self._turn_states.items()}
        self._pending_turn_requests[thread_id] = None
    try:
        yield cursors
    finally:
        with self._lock:
            del self._pending_turn_requests[thread_id]
            for state in list(self._turn_states.values()):
                if state.thread_id in (None, thread_id):
                    self._prune_turn_events(state)

subscription = self._router.prepare_turn(
    started.turn.id, thread_id, cursors, for_handle=for_handle
)

return retry_on_overload(
    lambda: self.request(method, params, response_model=response_model),
    max_attempts=max_attempts,
    initial_delay_s=initial_delay_s,
    max_delay_s=max_delay_s,
)

def retry_on_overload(
    op: Callable[[], T],
    *,
    max_attempts: int = 3,
    initial_delay_s: float = 0.25,
    max_delay_s: float = 2.0,
    jitter_ratio: float = 0.2,
) -> T:
    """Retry helper for transient server-overload errors."""

    if max_attempts < 1:
        raise ValueError("max_attempts must be >= 1")

    delay = initial_delay_s
    attempt = 0
    while True:
        attempt += 1
        try:
            return op()
        except Exception as exc:
            if attempt >= max_attempts:
                raise
            if not is_retryable_error(exc):
                raise

            jitter = delay * jitter_ratio
            sleep_for = min(max_delay_s, delay) + random.uniform(-jitter, jitter)
            if sleep_for > 0:
                time.sleep(sleep_for)
            delay = min(max_delay_s, delay * 2)

def register_turn_notifications(self, turn_id: str) -> None:
    """Start routing notifications for one turn into its dedicated queue."""
    self._router.register_turn(turn_id)

def next_turn_notification(self, turn_id: str) -> Notification:
    """Return the next routed notification for the requested turn id."""
    return self._router.next_turn_notification(turn_id)

def unregister_turn_notifications(self, turn_id: str) -> None:
    """Stop routing notifications for one turn into its dedicated queue."""
    self._router.unregister_turn(turn_id)

def next_login_notification(self, login_id: str) -> Notification:
    """Return the next routed notification for the requested login id."""
    return self._router.next_login_notification(login_id)

def unregister_login_notifications(self, login_id: str) -> None:
    """Stop routing notifications for one interactive login attempt."""
    self._router.unregister_login(login_id)

def _read_message(self) -> dict[str, JsonValue]:
    if self._proc is None or self._proc.stdout is None:
        raise TransportClosedError("Codex process is not running")

    line = self._proc.stdout.readline()
    if not line:
        raise TransportClosedError(
            f"Codex process closed stdout. stderr_tail={self._stderr_tail()[:2000]}"
        )

    try:
        message = json.loads(line)
    except json.JSONDecodeError as exc:
        raise CodexError(f"Invalid JSON-RPC line: {line!r}") from exc

    if not isinstance(message, dict):
        raise CodexError(f"Invalid JSON-RPC payload: {message!r}")
    return message

def _handle_server_request(self, msg: dict[str, JsonValue]) -> JsonObject:
    method = msg["method"]
    params = msg.get("params")
    if not isinstance(method, str):
        return {}
    return self._approval_handler(
        method,
        params if isinstance(params, dict) else None,
    )

def _coerce_notification(self, method: str, params: object) -> Notification:
    params_dict = params if isinstance(params, dict) else {}

    model = NOTIFICATION_MODELS.get(method)
    if model is None:
        return Notification(method=method, payload=UnknownNotification(params=params_dict))

    try:
        payload = model.model_validate(params_dict)
    except Exception:  # noqa: BLE001
        return Notification(method=method, payload=UnknownNotification(params=params_dict))
    return Notification(method=method, payload=payload)

async def _call_sync(
    self,
    fn: Callable[ParamsT, ReturnT],
    /,
    *args: ParamsT.args,
    **kwargs: ParamsT.kwargs,
) -> ReturnT:
    """Run a blocking sync-client operation without blocking the event loop."""
    return await asyncio.to_thread(fn, *args, **kwargs)

def register_goal_operation(self, thread_id: str) -> _GoalOperationState:
    """Register a private thread-scoped route for a logical goal turn."""
    return self._router.register_goal(thread_id)

return await self._call_sync(
    self._sync.thread_goal_set,
    thread_id,
    objective=objective,
    status=status,
)

def start_goal_operation(
    self,
    thread_id: str,
    objective: str,
) -> tuple[_GoalOperationState, str]:
    """Start a logical goal and wait for its runtime-generated first turn."""
    with self._thread_start_lock(thread_id):
        return self._start_goal_operation(thread_id, objective)

async def _start_turn(
    self,
    thread_id: str,
    input_items: list[JsonObject] | JsonObject | str,
    params: V2TurnStartParams | JsonObject | None,
    for_handle: bool,
) -> tuple[TurnStartResponse, _TurnSubscription | None]:
    operation = _TURN_START_EXECUTOR.submit(
        copy_context().run, self._sync._start_turn, thread_id, input_items, params, for_handle
    )
    try:
        return await asyncio.wrap_future(operation)
    except asyncio.CancelledError:

        def discard_cancelled_result(
            completed: Future[tuple[TurnStartResponse, _TurnSubscription | None]],
        ) -> None:
            try:
                _, subscription = completed.result()
            except BaseException:
                return
            if subscription is not None:
                subscription.close()

        operation.add_done_callback(discard_cancelled_result)
        raise

return await self._call_sync(
    self._sync.turn_steer,
    thread_id,
    expected_turn_id,
    input_items,
)

def _prune_turn_events(self, state: _TurnState) -> None:
    if state.thread_id in self._pending_turn_requests or (
        state.thread_id is None and self._pending_turn_requests
    ):
        return
    consumed = min(state.subscribers.values(), default=state.next_event)
    while state.first_event < consumed:
        del state.events[state.first_event]
        state.first_event += 1
    if not state.subscribers and self._turn_states.get(state.id) is state:
        del self._turn_states[state.id]

def _register_goal(self, state: _GoalOperationState) -> _GoalOperationState:
    with self._lock:
        if state.thread_id in self._goal_operations:
            raise RuntimeError(
                f"thread {state.thread_id!r} already has an active goal operation"
            )
        self._goal_operations[state.thread_id] = state
    return state

def _notification_login_id(self, notification: Notification) -> str | None:
    """Extract the login attempt id from completion notifications."""
    if notification.method != "account/login/completed":
        return None

    payload = notification.payload
    if isinstance(payload, AccountLoginCompletedNotification):
        return payload.login_id
    if isinstance(payload, UnknownNotification):
        raw_login_id = payload.params.get("loginId")
        if isinstance(raw_login_id, str):
            return raw_login_id
    return None

def _notification_turn_id(self, notification: Notification) -> str | None:
    """Extract routing ids from generated metadata or raw unknown payloads."""
    payload = notification.payload
    if isinstance(payload, UnknownNotification):
        raw_turn_id = payload.params.get("turnId")
        if isinstance(raw_turn_id, str):
            return raw_turn_id
        raw_turn = payload.params.get("turn")
        if isinstance(raw_turn, dict):
            raw_nested_turn_id = raw_turn.get("id")
            if isinstance(raw_nested_turn_id, str):
                return raw_nested_turn_id
        return None
    return notification_turn_id(payload)

def _terminal_goal_status(status: ThreadGoalStatus | None) -> bool:
    return status in {
        ThreadGoalStatus.paused,
        ThreadGoalStatus.blocked,
        ThreadGoalStatus.usage_limited,
        ThreadGoalStatus.budget_limited,
        ThreadGoalStatus.complete,
    }

def _logical_notification(notification: Notification, logical_turn_id: str) -> Notification:
    """Return a copy whose turn metadata uses the logical operation id."""
    payload = notification.payload
    if isinstance(payload, UnknownNotification):
        params = dict(payload.params)
        if isinstance(params.get("turnId"), str):
            params["turnId"] = logical_turn_id
        turn = params.get("turn")
        if isinstance(turn, dict) and isinstance(turn.get("id"), str):
            params["turn"] = {**turn, "id": logical_turn_id}
        return Notification(notification.method, UnknownNotification(params))

    turn_id = notification_turn_id(payload)
    if turn_id is None:
        return notification
    if hasattr(payload, "turn_id"):
        return Notification(
            notification.method,
            payload.model_copy(update={"turn_id": logical_turn_id}),
        )
    if hasattr(payload, "turn"):
        logical_turn = payload.turn.model_copy(update={"id": logical_turn_id})
        return Notification(
            notification.method,
            payload.model_copy(update={"turn": logical_turn}),
        )
    return notification

def _completion(
    self,
    method: str,
    payload: TurnCompletedNotification,
) -> Notification:
    logical_turn_id = self.state.logical_turn_id
    if logical_turn_id is None:
        raise RuntimeError("goal operation has not been bound to a logical turn id")
    return Notification(
        method,
        _logical_completion(
            payload,
            logical_turn_id=logical_turn_id,
            started=self.started,
            interrupted=self.state.explicit_interrupt(),
        ),
    )

def _logical_completion(
    completed: TurnCompletedNotification,
    *,
    logical_turn_id: str,
    started: Turn | None,
    interrupted: bool,
) -> TurnCompletedNotification:
    """Coalesce the final physical completion into one logical completion."""
    final_turn = completed.turn
    started_at = started.started_at if started is not None else final_turn.started_at
    duration_ms = final_turn.duration_ms
    if started_at is not None and final_turn.completed_at is not None:
        duration_ms = max(0, final_turn.completed_at - started_at) * 1000
    updates: dict[str, object] = {
        "id": logical_turn_id,
        "started_at": started_at,
        "duration_ms": duration_ms,
    }
    if interrupted:
        updates["status"] = TurnStatus.interrupted
    return completed.model_copy(update={"turn": final_turn.model_copy(update=updates)})

def _agent_message_item_from_thread_item(
    item: ThreadItem,
) -> AgentMessageThreadItem | None:
    thread_item = item.root if hasattr(item, "root") else item
    if isinstance(thread_item, AgentMessageThreadItem):
        return thread_item
    return None

def _raise_for_failed_turn(turn: Turn) -> None:
    if turn.status != TurnStatus.failed:
        return
    if turn.error is not None and turn.error.message:
        raise RuntimeError(turn.error.message)
    raise RuntimeError(f"turn failed with status {turn.status.value}")

def _final_assistant_response_from_items(items: list[ThreadItem]) -> str | None:
    last_unknown_phase_response: str | None = None

    for item in reversed(items):
        agent_message = _agent_message_item_from_thread_item(item)
        if agent_message is None:
            continue
        if agent_message.phase == MessagePhase.final_answer:
            return agent_message.text
        if agent_message.phase is None and last_unknown_phase_response is None:
            last_unknown_phase_response = agent_message.text

    return last_unknown_phase_response

def _to_wire_item(item: InputItem) -> JsonObject:
    if isinstance(item, TextInput):
        return {"type": "text", "text": item.text}
    if isinstance(item, ImageInput):
        return {"type": "image", "url": item.url}
    if isinstance(item, LocalImageInput):
        return {"type": "localImage", "path": item.path}
    if isinstance(item, SkillInput):
        return {"type": "skill", "name": item.name, "path": item.path}
    if isinstance(item, MentionInput):
        return {"type": "mention", "name": item.name, "path": item.path}
    raise TypeError(f"unsupported input item: {type(item)!r}")

def _assert_never_approval_mode(approval_mode: NoReturn) -> NoReturn:
    """Make approval mode mapping exhaustive for static type checkers."""
    raise AssertionError(f"Unhandled approval mode: {approval_mode!r}")

def _require_sandbox(sandbox: Sandbox) -> None:
    if isinstance(sandbox, Sandbox):
        return
    options = ", ".join(f"Sandbox.{value.name}" for value in Sandbox)
    raise ValueError(f"sandbox must be one of: {options}")

def _assert_never_sandbox(sandbox: NoReturn) -> NoReturn:
    """Make sandbox mapping exhaustive for static type checkers."""
    raise AssertionError(f"Unhandled sandbox: {sandbox!r}")

def _source_tree_project_version() -> str | None:
    pyproject_path = Path(__file__).resolve().parents[2] / "pyproject.toml"
    if not pyproject_path.exists():
        return None

    match = re.search(
        r'(?m)^version = "([^"]+)"$',
        pyproject_path.read_text(encoding="utf-8"),
    )
    if match is None:
        return None
    return match.group(1)

def is_retryable_error(exc: BaseException) -> bool:
    """True if the exception is a transient overload-style error."""

    if isinstance(exc, ServerBusyError):
        return True

    if isinstance(exc, JsonRpcError):
        return _is_server_overloaded(exc.data)

    return False

def _is_server_overloaded(data: Any) -> bool:
    if data is None:
        return False

    if isinstance(data, str):
        return data.lower() == "server_overloaded"

    if isinstance(data, dict):
        direct = data.get("codex_error_info") or data.get("codexErrorInfo") or data.get("errorInfo")
        if isinstance(direct, str) and direct.lower() == "server_overloaded":
            return True
        if isinstance(direct, dict):
            for value in direct.values():
                if isinstance(value, str) and value.lower() == "server_overloaded":
                    return True
        for value in data.values():
            if _is_server_overloaded(value):
                return True

    if isinstance(data, list):
        return any(_is_server_overloaded(value) for value in data)

    return False

def _contains_retry_limit_text(message: str) -> bool:
    lowered = message.lower()
    return "retry limit" in lowered or "too many failed attempts" in lowered

def _source_tree_runtime_dependency_version() -> str | None:
    """Read the runtime dependency pin when the SDK is running from a checkout."""
    pyproject_path = Path(__file__).resolve().parent / "pyproject.toml"
    if not pyproject_path.exists():
        return None

    match = re.search(_runtime_dependency_pin_pattern(), pyproject_path.read_text())
    if match is None:
        return None
    return match.group(1)

def _installed_sdk_runtime_dependency_version() -> str | None:
    """Read the runtime dependency pin from installed package metadata."""
    requirements = importlib.metadata.requires(SDK_PACKAGE_NAME) or []
    for requirement in requirements:
        match = re.search(_runtime_dependency_pin_pattern(), requirement)
        if match is not None:
            return match.group(1)
    return None

def pinned_runtime_version() -> str:
    """Return the exact runtime version pinned by the SDK package dependency."""
    source_pin = _source_tree_runtime_dependency_version()
    if source_pin is not None:
        return _normalized_package_version(source_pin)

    try:
        installed_pin = _installed_sdk_runtime_dependency_version()
    except importlib.metadata.PackageNotFoundError as exc:
        raise RuntimeSetupError(
            f"Unable to resolve {SDK_PACKAGE_NAME} metadata for runtime pinning."
        ) from exc
    if installed_pin is None:
        raise RuntimeSetupError(
            f"Unable to resolve {PACKAGE_NAME} dependency pin from {SDK_PACKAGE_NAME}."
        )
    return _normalized_package_version(installed_pin)

def _github_token() -> str | None:
    for env_name in ("GH_TOKEN", "GITHUB_TOKEN"):
        token = os.environ.get(env_name)
        if token:
            return token
    return None

def platform_asset_name() -> str:
    system = platform.system().lower()
    machine = platform.machine().lower()

    if system == "darwin":
        if machine in {"arm64", "aarch64"}:
            return "codex-package-aarch64-apple-darwin.tar.gz"
        if machine in {"x86_64", "amd64"}:
            return "codex-package-x86_64-apple-darwin.tar.gz"
    elif system == "linux":
        if machine in {"aarch64", "arm64"}:
            return "codex-package-aarch64-unknown-linux-musl.tar.gz"
        if machine in {"x86_64", "amd64"}:
            return "codex-package-x86_64-unknown-linux-musl.tar.gz"
    elif system == "windows":
        if machine in {"aarch64", "arm64"}:
            return "codex-package-aarch64-pc-windows-msvc.tar.gz"
        if machine in {"x86_64", "amd64"}:
            return "codex-package-x86_64-pc-windows-msvc.tar.gz"

    raise RuntimeSetupError(
        f"Unsupported runtime artifact platform: system={platform.system()!r}, "
        f"machine={platform.machine()!r}"
    )

def _release_metadata(version: str) -> dict[str, object]:
    release_tag = _release_tag(version)
    url = f"https://api.github.com/repos/{REPO_SLUG}/releases/tags/{release_tag}"
    token = _github_token()
    attempts = [True, False] if token is not None else [False]
    last_error: urllib.error.HTTPError | None = None

    for include_auth in attempts:
        headers = {
            "Accept": "application/vnd.github+json",
            "User-Agent": "codex-python-runtime-setup",
        }
        if include_auth and token is not None:
            headers["Authorization"] = f"Bearer {token}"

        request = urllib.request.Request(url, headers=headers)
        try:
            with urllib.request.urlopen(request) as response:
                return json.load(response)
        except urllib.error.HTTPError as exc:
            last_error = exc
            if include_auth and exc.code == 401:
                continue
            break

    assert last_error is not None
    raise RuntimeSetupError(
        f"Failed to resolve release metadata for {release_tag} from {REPO_SLUG}: "
        f"{last_error.code} {last_error.reason}"
    ) from last_error

def _github_api_headers(accept: str) -> dict[str, str]:
    headers = {
        "Accept": accept,
        "User-Agent": "codex-python-runtime-setup",
    }
    token = _github_token()
    if token is not None:
        headers["Authorization"] = f"Bearer {token}"
    return headers

def _runtime_dependency_pin_pattern() -> str:
    """Match the exact runtime dependency pin in TOML and wheel metadata."""
    return rf'{re.escape(PACKAGE_NAME)}\s*==\s*"?([^",;\s]+)"?'

def _platform_tag() -> str:
    from packaging.tags import sys_tags

    return next(iter(sys_tags())).platform

def bundled_package_dir() -> Path:
    path = Path(__file__).resolve().parent
    metadata_path = path / PACKAGE_METADATA_FILENAME
    if not metadata_path.is_file():
        raise FileNotFoundError(
            f"{PACKAGE_NAME} is installed but missing its package metadata at {metadata_path}"
        )
    return path

