def fields(self) -> dict[str, frozenset[str]]:
    try:
        with TemporaryDirectory(prefix="codex-sdk-schema-") as directory:
            subprocess.run(
                [*self.command, "generate-json-schema", "--experimental", "--out", directory],
                cwd=self.cwd,
                env=self.env,
                capture_output=True,
                check=True,
                timeout=30,
            )
            result = {}
            for method, name in (
                ("turn/start", "TurnStartParams"),
                ("thread/resume", "ThreadResumeParams"),
                ("thread/fork", "ThreadForkParams"),
            ):
                schema = json.loads((Path(directory) / "v2" / f"{name}.json").read_text())
                properties = schema.get("properties") if isinstance(schema, dict) else None
                if not isinstance(properties, dict):
                    raise ValueError(f"Missing properties in {name} schema")
                result[method] = frozenset(properties)
            return result
    except (OSError, subprocess.SubprocessError, ValueError) as exc:
        raise ValueError("Could not inspect the unversioned CLI's experimental schema") from exc

def _installed_codex_path() -> Path:
    try:
        from codex_cli_bin import bundled_codex_path
    except ImportError as exc:
        raise FileNotFoundError(
            "Unable to locate the pinned Codex runtime. Install the published SDK build "
            f"with its {RUNTIME_PKG_NAME} dependency, or set CodexConfig.codex_bin "
            "explicitly."
        ) from exc

    return bundled_codex_path()

def bundled_codex_path() -> Path:
    exe = "codex.exe" if os.name == "nt" else "codex"
    path = bundled_package_dir() / "bin" / exe
    if not path.is_file():
        raise FileNotFoundError(
            f"{PACKAGE_NAME} is installed but missing its packaged codex binary at {path}"
        )
    return path

def initialize(self, version: str, build_data: dict[str, object]) -> None:
    del version
    if self.target_name == "sdist":
        raise RuntimeError(
            "openai-codex-cli-bin is wheel-only; build and publish platform wheels only."
        )

    platform_tag = self.config.get("platform-tag") or os.environ.get(
        "CODEX_CLI_BIN_PLATFORM_TAG"
    )
    if not isinstance(platform_tag, str) or not platform_tag:
        platform_tag = _platform_tag()

    build_data["pure_python"] = False
    build_data["infer_tag"] = False
    build_data["tag"] = f"py3-none-{platform_tag}"

def __init__(self, config: CodexConfig | None = None) -> None:
    self._client = CodexClient(config=config)
    try:
        self._client.start()
        self._init = validate_initialize_metadata(self._client.initialize())
    except Exception:
        self._client.close()
        raise

def run(self) -> TurnResult:
    """Consume the turn stream and return its completed result."""
    stream = self.stream()
    try:
        return _collect_turn_result(stream, turn_id=self.id)
    finally:
        stream.close()

def _default_approval_handler(self, method: str, params: JsonObject | None) -> JsonObject:
    """Accept approval requests when the caller did not provide a handler."""
    if method == "item/commandExecution/requestApproval":
        return {"decision": "accept"}
    if method == "item/fileChange/requestApproval":
        return {"decision": "accept"}
    return {}

def process(self, notification: Notification) -> tuple[list[Notification], bool]:
    logical_turn_id = self.state.logical_turn_id
    if logical_turn_id is None:
        raise RuntimeError("goal operation has not been bound to a logical turn id")

    payload = notification.payload
    if isinstance(payload, TurnStartedNotification):
        self.active = True
        if self.started is not None:
            return [], False
        self.started = payload.turn
        return [_logical_notification(notification, logical_turn_id)], False

    if isinstance(payload, TurnCompletedNotification):
        self.active = False
        self.last_completed = payload
        if payload.turn.status == TurnStatus.interrupted:
            return [
                self._completion(
                    notification.method,
                    self.failed_completion or payload,
                )
            ], True
        if payload.turn.status == TurnStatus.failed:
            self.failed_completion = payload
            if self.cleared or _terminal_goal_status(self.status):
                self.state.finish()
                return [self._completion(notification.method, payload)], True
            return [], False
        if self.status is None and not self.cleared:
            raise RuntimeError(
                "the connected Codex runtime did not activate goal mode for this turn"
            )
        if self.cleared or _terminal_goal_status(self.status):
            self.state.finish()
            return [
                self._completion(
                    notification.method,
                    self.failed_completion or payload,
                )
            ], True
        return [], False

    events = [_logical_notification(notification, logical_turn_id)]
    if isinstance(payload, ThreadGoalUpdatedNotification):
        self.status = payload.goal.status
        if self.status == ThreadGoalStatus.active:
            self.cleared = False
        events = []
    elif isinstance(payload, ThreadGoalClearedNotification):
        self.cleared = True
        events = []

    if (
        not self.active
        and self.last_completed is not None
        and (self.cleared or _terminal_goal_status(self.status))
    ):
        self.state.finish()
        events.append(
            self._completion(
                "turn/completed",
                self.failed_completion or self.last_completed,
            )
        )
        return events, True
    return events, False

def wait(self) -> AccountLoginCompletedNotification:
    """Wait for this browser login attempt's completion notification."""
    return self._client.wait_for_login_completed(self.login_id)

def cancel(self) -> CancelLoginAccountResponse:
    """Cancel this browser login attempt."""
    return self._client.account_login_cancel(self.login_id)

def wait_for_login_completed(
    self,
    login_id: str,
) -> AccountLoginCompletedNotification:
    """Block until the matching interactive login attempt completes."""
    self.register_login_notifications(login_id)
    try:
        while True:
            notification = self.next_login_notification(login_id)
            if (
                notification.method == "account/login/completed"
                and isinstance(notification.payload, AccountLoginCompletedNotification)
                and notification.payload.login_id == login_id
            ):
                return notification.payload
    finally:
        self.unregister_login_notifications(login_id)

def metadata(self) -> InitializeResponse:
    if self._init is None:
        raise RuntimeError(
            "AsyncCodex is not initialized yet. Prefer `async with AsyncCodex()`; "
            "initialization also happens on first awaited API use."
        )
    return self._init

def __next__(self) -> Notification:
    if self._closed:
        raise StopIteration
    try:
        while not self._pending:
            notification = self.next_notification()
            events, completed = self._cursor.process(notification)
            self._pending.extend(events)
            if completed:
                self._finish()
        return self._pending.popleft()
    except _GoalStreamClosed:
        self.close()
        raise StopIteration from None
    except KeyboardInterrupt:
        self.cancel_goal()
        self.close()
        raise
    except BaseException:
        self.close()
        raise

async def __anext__(self) -> Notification:
    if self._closed:
        raise StopAsyncIteration
    try:
        while not self._pending:
            notification = await self.next_notification()
            events, completed = self._cursor.process(notification)
            self._pending.extend(events)
            if completed:
                self._finish()
        return self._pending.popleft()
    except _GoalStreamClosed:
        await self.aclose()
        raise StopAsyncIteration from None
    except asyncio.CancelledError:
        await self.cancel_goal()
        await self.aclose()
        raise
    except BaseException:
        await self.aclose()
        raise

